using System.Numerics;
using System.Runtime.InteropServices;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;
        int vecCount = Vector<float>.Count;

        if (values.Length >= vecCount * 4)
        {
            var vecs = MemoryMarshal.Cast<float, Vector<float>>(values);

            // Four independent accumulators to hide multiply latency
            var acc0 = Vector<float>.One;
            var acc1 = Vector<float>.One;
            var acc2 = Vector<float>.One;
            var acc3 = Vector<float>.One;

            int vi = 0;
            int limit = vecs.Length - 3;
            for (; vi < limit; vi += 4)
            {
                acc0 *= vecs[vi];
                acc1 *= vecs[vi + 1];
                acc2 *= vecs[vi + 2];
                acc3 *= vecs[vi + 3];
            }

            // Merge accumulators
            acc0 = (acc0 * acc1) * (acc2 * acc3);

            // Handle remaining full vectors
            for (; vi < vecs.Length; vi++)
                acc0 *= vecs[vi];

            // Horizontal reduce
            float product = 1f;
            for (int j = 0; j < vecCount; j++)
                product *= acc0[j];

            // Scalar tail (elements not filling a full vector)
            i = vecs.Length * vecCount;
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Short-path scalar fallback
        float result = values[0];
        for (i = 1; i < values.Length; i++)
            result *= values[i];
        return result;
    }
}

